//! Native evidence only: retain a valid API graph and replace only q's typed parameter group.
use sketchpad_rs::document::{Document,Kind,records};use std::fs;
fn main(){let b=fs::read("/tmp/transformed_arc48_api_numeric_dilation_input.gsp").unwrap();let d=Document::from_bytes(&b,None).unwrap();d.verify_roundtrip().unwrap();let Kind::Parameter(mut group)=d.objects[16].kind.clone()else{panic!()};group.set_value(0.).unwrap();let rs=records(&b).unwrap();let at=d.objects[16].header_offset.unwrap();let i=rs.iter().position(|r|r.kind==0x7d0&&r.data.start==at).unwrap();let j=(i..rs.len()).find(|&x|rs[x].kind==0x7d7).unwrap();let mut patch=b.clone();patch.splice(rs[i].data.start-8..rs[j].data.end,group.as_bytes().iter().copied());let r=Document::from_bytes(&patch,None).unwrap();assert_eq!(r.unitless_numeric_value(17),Some(0.));assert!(r.arc_points(18,4).is_none());assert!(r.position(19).is_none());assert!(r.arc_angle_degrees(20).is_none());assert!(r.arc_length_cm(21).is_none());println!("retained source13 final18 point19 angle20 length21 zero17 bytes{} strict{:?}",patch.len(),r.verify_roundtrip());fs::write("/tmp/transformed_arc48_api_numeric_dilation_zero_leaves_input.gsp",patch).unwrap();}
